{id:'a3',jobId:'job-1041',driverId:'d3',status:'completed',startTime:hoursAgo(20),arrivalTime:hoursAgo(19),departureTime:hoursAgo(13),endTime:hoursAgo(12),payMode:'percentage',payRate:28,payPercent:30,loads:[{id:'l2',qtyBbl:0},{id:'l3',qtyBbl:0}],pauses:[],standbyCharge:0,washoutCost:0,jsa:{signed:true,sample:true,driverName:'Chris Davis',repName:'Sam Rivera',signedAt:hoursAgo(19)},signatures:[],manual:false}],audit:[{id:uid(),at:hoursAgo(1),message:'Sample workspace created. All people, jobs and activity are demo data.'}],pinHashes:{},invoices:{}};}
function blankState(){return {company:COMPANY_NAME,jobs:[],assignments:[],drivers:[],trucks:[],wells:[],customers:[],representatives:[],roles:[],users:[],invoices:{},audit:[],locations:{},dispatchContacts:[],defaultDispatchContact:null,officeManagerContact:null,purgedInvoiceJobIds:[]};}
let state=blankState(),authUser=null,revision=0,saving=false,signInTimeZone;
let view='overview',search='',jobFilter='all',selectedDriver='',toastTimer,roleId='',masterTab='customers',masterShowDeleted=false,gps;
let connectionMonitor,wellPicker,softwareUpdates,updateServerSettings,modalCleanups=[],serverClockOffset=0,pdfDownloading=false;
let liveMap,liveMapUi={search:'',status:'all',selectedDriver:''},mapReadStatus={at:null,error:''};
let customerTracking=null,customerTrackingTimer=null,customerTrackingRequest=null,customerMapStatus={};
let customerInvoiceRequest=null,customerInvoiceStatus={};
let invoiceFilters={groupBy:'all',entityId:'',status:'all'};
let workReportFilters={};
const completionNoteDrafts=new Map();
const api=createApiClient({onUnauthorized:()=>{if(authUser){stopCustomerRequests();if(isCustomerSupervisor())$('#app').innerHTML='';authUser=null;softwareUpdates.stop();updateServerSettings.stop();completionNoteDrafts.clear();gps?.stop();liveMap?.destroy({preserveView:false});close();void boot();}}});
const can=permission=>Boolean(authUser)&&canPermission(state,roleId,permission);
const isAdmin=()=>roleId==='admin';
const isCustomerSupervisor=()=>roleId==='customer-supervisor';
const isDriverMode=()=>Boolean(authUser?.driverId)&&(roleId==='driver'||can('driver_work'));
const canMarkInvoicePaid=()=>can('view_invoices')&&!isDriverMode()&&(isAdmin()||roleId==='accounting');
function context(){return {get state(){return state;},get timeZone(){return workspaceZone();},get masterTab(){return masterTab;},getMasterShowDeleted:()=>masterShowDeleted,get gps(){return gps;},get mapReadStatus(){return mapReadStatus;},representativeForJob,mountWellMapPicker:options=>{void wellPicker.open(options);return()=>wellPicker.destroy();},registerModalCleanup:cleanup=>{if(typeof cleanup==='function')modalCleanups.push(cleanup);},can,getRoleId:()=>roleId,esc,field,rateField,icon,badge,money,modal,close,save,notify,render,driver,job,assignment,now,uid,date,getSelectedDriver:()=>selectedDriver,accountApi:api,refreshWorkspace,recordLocation:payload=>api.recordLocation(payload),uploadPhoto:payload=>api.uploadPhoto(payload),uploadSupportingDocument:payload=>api.uploadSupportingDocument(payload)};}
function workspaceForRole(loaded){
  if(!isCustomerSupervisor())return {...blankState(),...loaded};
  return {...blankState(),company:loaded.company||COMPANY_NAME,timeZone:loaded.timeZone,
    customer:loaded.customer,customerInvoices:customerIssuedInvoices(loaded.customerInvoices)};
}
function installWorkspaceSnapshot(data){if(!data?.state||!Number.isSafeInteger(data.revision)||data.revision<revision)return false;state=workspaceForRole(data.state);revision=data.revision;mapReadStatus={at:now(),error:''};render();return true;}
async function refreshWorkspace(){const actor=authUser;const [data]=await Promise.all([api.getWorkspace(),loadCompanyBranding(api)]);if(authUser===actor)installWorkspaceSnapshot(data);return data;}
function setBusy(value){saving=value;document.body.classList.toggle('saving',value);let overlay=document.querySelector('#save-blocker');if(value&&!overlay){overlay=document.createElement('div');overlay.id='save-blocker';overlay.className='save-blocker';overlay.setAttribute('role','status');overlay.textContent='Saving securely…';document.body.appendChild(overlay);}else if(!value)overlay?.remove();}
function bootstrapState(){let initial;try{initial=JSON.parse(localStorage.getItem(STORAGE))||seed();}catch{initial=seed();}upgradeData(initial);initial.company=COMPANY_NAME;initial.users=[];delete initial.pinHashes;for(const a of initial.assignments){const j=initial.jobs.find(j=>j.id===a.jobId);for(const k of ['billingMode','hourlyRate','loadRate','fluidSaleRate','fluidCostRate'])a[k]??=j?.[k];a.driverName??=initial.drivers.find(d=>d.id===a.driverId)?.name;}return initial;}
async function enterWorkspace(session){
  stopCustomerRequests();
  const account=session.user;
  authUser=account;roleId=authUser.roleId;selectedDriver=authUser.driverId||'';masterShowDeleted=false;
  const data=await api.getWorkspace();
  if(authUser!==account)return;
  if(isCustomerSupervisor()&&!data?.state?.customer?.id)throw new Error('Your customer workspace is unavailable.');
  const loaded=data.state?data:await api.initWorkspace(bootstrapState());
  state=workspaceForRole(loaded.state);revision=loaded.revision;mapReadStatus={at:now(),error:''};
  liveMapUi={search:'',status:'all',selectedDriver:''};liveMap?.destroy({preserveView:false});
  view=isCustomerSupervisor()?'live-maps':isDriverMode()?'driver':'overview';
  invoiceFilters={groupBy:'all',entityId:'',status:'all'};workReportFilters={};
  document.body.classList.remove('auth-screen');render();void softwareUpdates.start();
}
async function boot(){const brandingReady=loadCompanyBranding(api);try{const session=await api.session();await brandingReady;await enterWorkspace(session);}catch(error){authUser=null;softwareUpdates.stop();updateServerSettings.stop();document.body.classList.remove('driver-mode');runModalCleanups();liveMap?.destroy({preserveView:false});api.clearSession();let needsSetup=false,setupTokenRequired=false;try{const setup=await api.getSetup();needsSetup=Boolean(setup.needsSetup);setupTokenRequired=Boolean(setup.setupTokenRequired);signInTimeZone=setup.timeZone;}catch{}await brandingReady;refreshRuntimeClock();renderLogin({container:$('#app'),api,needsSetup,setupTokenRequired,error:error.status===401?undefined:error.message,onAuthenticated:enterWorkspace});}}
const assignmentDriver=a=>({...driver(a.driverId),name:a.driverName||driver(a.driverId)?.name,truck:a.truckUnit||driver(a.driverId)?.truck});
function save(message,metadata={}){if(saving){const rejected=Promise.reject(new Error('Wait for the current change to finish.'));rejected.catch(()=>{});return rejected;}const submitted=structuredClone(state);delete submitted.locations;if(message)submitted._reason=message;Object.assign(submitted,metadata.stateMetadata||{});setBusy(true);const task=(async()=>{try{const data=await api.saveWorkspace(submitted,revision,metadata);state={...blankState(),...data.state};revision=data.revision;render();return true;}catch(error){try{await refreshWorkspace();}catch{}notify(error.status===409?'The workspace changed. It has been refreshed; please repeat your action.':error.message);throw error;}finally{setBusy(false);}})();task.catch(()=>{});return task;}
function notify(msg){const el=$('#toast');el.textContent=msg;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500);}
const driver=id=>state.drivers.find(d=>d.id===id);
const job=id=>state.jobs.find(j=>j.id===id);
const assignment=id=>state.assignments.find(a=>a.id===id);
function representativeForJob(j,kind='arrival'){
  const prefix=kind==='departure'&&j.representativeMode==='separate'?'departure':'arrival';
  return {id:j[prefix+'RepId']||j.repId,name:j[prefix+'RepName']||j.repName,phone:j[prefix+'RepPhone']??j.repPhone,email:j[prefix+'RepEmail']??j.repEmail};
}
function representativeRows(j){const a=representativeForJob(j),d=representativeForJob(j,'departure');return j.representativeMode==='separate'?[['Arrival representative',a.name],['Arrival phone',a.phone],['Departure representative',d.name],['Departure phone',d.phone]]:[['Arrival & departure representative',a.name],['Representative phone',a.phone]];}
function invoiceContext(){return {state,timeZone:workspaceZone(),assigned,assignment,assignmentDriver,money,num,date,esc,icon,badge,ticketHtml,calculateInvoice,can,logoHtml:companyLogoHtml,showPaymentReference:can('view_invoices')&&!isDriverMode()&&roleId!=='client'};}

const assigned=j=>state.assignments.filter(a=>a.jobId===j.id);
const active=a=>!['completed','assigned'].includes(a.status);
const titleCase=s=>s.replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase());
const badge=(text,color='gray')=>`<span class="badge ${color}"><span class="dot"></span>${esc(text)}</span>`;
const initials=name=>esc(name.split(' ').map(x=>x[0]).slice(0,2).join(''));
function jobStatus(j){const aa=assigned(j);return aa.length&&aa.every(a=>a.status==='completed')?'completed':aa.some(a=>a.status!=='assigned')?'in-progress':'scheduled';}
function dataButton(action,label,extra='',cls='btn'){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function stat(label,value,note,kind=''){return `<div class="stat-card"><div class="stat-label">${label}</div><div class="stat-value ${kind}">${value}</div><div class="stat-note">${note}</div></div>`;}
function header(eyebrow,title,sub,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="top-actions">${buttons}</div></div>`;}
const viewPermission={overview:'view_jobs',dispatch:'dispatch_jobs',driver:'driver_work',fleet:'view_masters',masters:'view_masters',tracking:'view_tracking','live-maps':'view_tracking',invoices:'view_invoices',reports:'view_invoices',payroll:'view_payroll',settings:'manage_roles'};
function navItems(){return [['overview','grid','Overview'],['dispatch','truck','Dispatch board'],['live-maps','pin','Live Maps'],['tracking','pin','Fleet locations'],['masters','settings','Master data'],['fleet','users','Drivers & fleet'],['invoices','file','Invoices'],['reports','chart','Report'],['payroll','clock','Weekly payroll'],['settings','settings','Settings']].filter(n=>can(viewPermission[n[0]]));}
function accountBanner(){return `<div class="preview-strip"><span><strong>${esc(authUser?.name||authUser?.username)}</strong> · ${esc(state.roles.find(r=>r.id===roleId)?.name||titleCase(roleId))}</span><button class="btn small" data-action="logout">Sign out</button></div>`;}
const customerPages=[['live-maps','pin','Live Map'],['invoices','file','Invoices']];
const customerMapVisible=()=>Boolean(authUser&&isCustomerSupervisor()&&view==='live-maps'&&!document.hidden);

function customerMapContext(){
  return {get state(){return customerTracking||{};},get timeZone(){return workspaceZone();},
    get mapReadStatus(){return customerMapStatus;},customerTracking:true,icon,date,
    mapNow:()=>Date.now()+serverClockOffset,can:permission=>permission==='view_tracking'&&isCustomerSupervisor(),
    getRoleId:()=>roleId};
}

function stopCustomerTracking(){
  const hadTracking=customerTrackingTimer!==null||customerTrackingRequest||customerTracking;
  if(customerTrackingTimer!==null)clearInterval(customerTrackingTimer);
  customerTrackingTimer=null;
  customerTrackingRequest?.abort();
  customerTrackingRequest=null;
  customerTracking=null;
  customerMapStatus={};
  if(hadTracking&&isCustomerSupervisor()&&view==='live-maps')liveMap?.update(customerMapContext(),liveMapUi);
}

function stopCustomerRequests(){
  stopCustomerTracking();
  customerInvoiceRequest?.abort();
  customerInvoiceRequest=null;
  customerInvoiceStatus={};
}

async function pollCustomerTracking(){
  if(!customerMapVisible()||customerTrackingRequest)return;
  const request=new AbortController();
  customerTrackingRequest=request;
  const timeout=setTimeout(()=>request.abort(),5000);
  const isCurrent=()=>customerTrackingRequest===request&&customerMapVisible();
  try{
    const result=await api.getCustomerTracking(request.signal);
    if(!isCurrent())return;
    if(request.signal.aborted||!result||!['jobs','assignments','drivers','trucks'].every(key=>Array.isArray(result[key]))
        ||!result.locations||typeof result.locations!=='object'||Array.isArray(result.locations)){
      throw new Error('Live locations unavailable.');
    }
    const {jobs,assignments,drivers,trucks,locations}=result;
    customerTracking={jobs,assignments,drivers,trucks,locations};
    customerMapStatus={at:now()};
  }catch{
    if(!isCurrent())return;
    customerTracking=null;
    customerMapStatus={error:true};
  }finally{
    clearTimeout(timeout);
    if(customerTrackingRequest===request)customerTrackingRequest=null;
  }
  if(customerMapVisible())liveMap?.update(customerMapContext(),liveMapUi);
}

function startCustomerTracking(){
  if(!customerMapVisible()||customerTrackingTimer!==null)return;
  customerTrackingTimer=setInterval(pollCustomerTracking,3000);
  void pollCustomerTracking();
}

async function refreshCustomerInvoices(){
  if(!authUser||!isCustomerSupervisor()||view!=='invoices')return;
  customerInvoiceRequest?.abort();
  const request=new AbortController(),account=authUser;
  customerInvoiceRequest=request;
  customerInvoiceStatus={loading:true};
  state.customerInvoices=[];
  renderCustomerWorkspace();
  const isCurrent=()=>authUser===account&&view==='invoices'&&customerInvoiceRequest===request;
  const timeout=setTimeout(()=>request.abort(),7000);
  try{
    const result=await api.getWorkspace(request.signal);
    if(!isCurrent())return;
    if(request.signal.aborted||result?.state?.customer?.id!==state.customer?.id||!Array.isArray(result?.state?.customerInvoices)){
      throw new Error('Invoices unavailable.');
    }
    state=workspaceForRole(result.state);
    customerInvoiceStatus={};
  }catch{
    if(!isCurrent())return;
    customerInvoiceStatus={error:'Issued invoices are unavailable. Select Invoices to try again.'};
  }finally{
    clearTimeout(timeout);
    if(customerInvoiceRequest===request)customerInvoiceRequest=null;
  }
  if(authUser===account&&view==='invoices')renderCustomerWorkspace();
}

async function openCustomerInvoice(jobId){
  if(view!=='invoices'||!state.customerInvoices.some(invoice=>invoice.jobId===jobId)){
    throw new Error('This invoice is no longer available.');
  }
  modal('Invoice details','<div id="customer-invoice-detail" role="status">Loading invoice…</div>');
  const node=$('#customer-invoice-detail'),account=authUser,request=new AbortController();
  const timeout=setTimeout(()=>request.abort(),7000);
  modalCleanups.push(()=>{request.abort();clearTimeout(timeout);});
  const isCurrent=()=>authUser===account&&view==='invoices'&&$('#customer-invoice-detail')===node;
  try{
    const {invoice}=await api.getCustomerInvoice(jobId,request.signal);
    if(!isCurrent())return;
    if(request.signal.aborted||invoice?.jobId!==jobId)throw new Error('Invoice unavailable.');
    node.innerHTML=customerInvoiceDetailView(invoice,{esc,date,money,num});
  }catch(error){
    if(!isCurrent())return;
    if(error.status===403||error.status===404){
      state.customerInvoices=error.status===403?[]:state.customerInvoices.filter(invoice=>invoice.jobId!==jobId);
      renderCustomerWorkspace();
      node.textContent='This invoice is no longer available.';
    }else node.textContent='The invoice could not be loaded. Close this window and try again.';
  }finally{clearTimeout(timeout);}
}

function renderCustomerWorkspace(){
  if(!customerPages.some(([key])=>key===view))view='live-maps';
  const customer=state.customer?.name||'Customer workspace',label=customerPages.find(([key])=>key===view)[2];
  $('#app').innerHTML=`<aside class="sidebar"><div class="brand">${companyLogoHtml('sidebar-company-logo')}
      <span class="brand-company">${esc(state.company)}</span></div><div class="nav-label">CUSTOMER WORKSPACE</div>
    <nav class="nav-list" aria-label="Main navigation">${customerPages.map(([id,symbol,caption])=>`<button type="button" data-view="${id}"${view===id?' class="active" aria-current="page"':''}><span class="nav-icon">${icon(symbol)}</span>${caption}</button>`).join('')}</nav></aside>
    <div class="main"><header class="topbar"><div>${esc(customer)} <span class="breadcrumb-slash">/</span> <strong>${label}</strong></div></header>
      ${accountBanner()}<main class="content" id="main-content">${view==='live-maps'?
        liveMapsView(customerMapContext(),liveMapUi):customerInvoiceListView({state,esc,date,money},customerInvoiceStatus)}</main></div>`;
  if(view==='live-maps'){bindLiveMap(customerMapContext);startCustomerTracking();}
}

async function onCustomerWorkspaceClick(target){
  const navigation=target.closest('[data-view]');
  if(navigation){
    const next=navigation.dataset.view;
    if(!customerPages.some(([key])=>key===next))return;
    stopCustomerRequests();
    liveMap?.destroy({preserveView:false});
    liveMapUi={search:'',status:'all',selectedDriver:''};
    view=next;
    close();
    if(view==='invoices')await refreshCustomerInvoices();
    else renderCustomerWorkspace();
    window.scrollTo(0,0);
    return;
  }
  const button=target.closest('[data-action]');
  if(!button)return;
  const {action,id}=button.dataset;
  try{
    if(action==='logout'){await signOut();return;}
    if(action==='close'){close();return;}
    if(action==='customer-invoice'){await openCustomerInvoice(id);return;}
    if(!customerMapVisible())return;
    if(action==='map-fit')liveMap?.fit();
    if(action==='map-focus')liveMap?.focus(id);
    if(action==='map-refresh')await pollCustomerTracking();
  }catch(error){notify(error.message);}
}

document.addEventListener('visibilitychange',()=>{
  if(!authUser||!isCustomerSupervisor()||view!=='live-maps')return;
  if(document.hidden)stopCustomerTracking();
  else startCustomerTracking();
});
