  if(a.status==='accepted'&&!a.jsa?.signed)return dataButton('jsa',icon('shield')+' Review & sign JSA',id,'btn primary');
  if(a.status==='accepted')return dataButton('arrival','Confirm arrival',id,'btn primary');
  if(a.status==='on-location'){
    if(missingPerLoadRecords(a))return dataButton('add-load','Record a completed load before departure',id,'btn primary');
    const water=enabledHourlyFluidServices(job(a.jobId)).length;
    return dataButton('departure',water?'Finish work · confirm water deliveries':'Finish work · confirm departure',id,'btn primary');
  }
  if(a.status==='off-location'){
    if(canRecoverMissedLoads(a))return dataButton('recover-loads','Record missed loads',id,'btn primary');
    if(missingPerLoadRecords(a))return '<p class="notice">Ask the office to check your departure record before completing this job.</p>';
    return dataButton('complete','Back at yard · complete job '+icon('check'),id,'btn primary');
  }
  return '<span class="badge green">✓ Completed · ticket ready</span>';
}
function attachmentsHtml(j){return `<h3>Attachments <small>(${j.attachments?.length||0})</small></h3>${j.attachments?.length?j.attachments.map(f=>`<p><button class="text-btn" data-action="download-attachment" data-job="${esc(j.id)}" data-id="${esc(f.id)}">${icon('file')} ${esc(f.name)}</button></p>`).join(''):'<p class="muted">No attachments added.</p>'}`;}
function downloadJobAttachment(jobId,attachmentId){
  const record=job(jobId);
  if(!record||(isDriverMode()?!assigned(record).some(a=>a.driverId===selectedDriver):!can('view_jobs'))){
    throw new Error('Attachment access is limited to this job’s authorized users.');
  }
  const attachment=record.attachments?.find(item=>item.id===attachmentId);
  if(!attachment)throw new Error('Attachment not found.');
  const file=typeof attachment.data==='string'&&/^data:(application\/pdf|image\/(?:jpeg|png)|text\/(?:plain|csv));base64,([A-Za-z0-9+/=\r\n]+)$/.exec(attachment.data);
  if(!file)throw new Error('This attachment format cannot be downloaded.');
  let bytes;
  try{bytes=Uint8Array.from(atob(file[2]),character=>character.charCodeAt(0));}
  catch{throw new Error('This attachment could not be read.');}
  download(attachment.name,bytes,file[1]);
}
