n><div class="notice">${icon('clock')} <span>Overtime spans all hourly assignments in the week; percentage pay uses haul revenue only. Automatic weekly email is not connected.</span></div>`;}
function editTimes(id){
  if(!isAdmin())throw new Error('Only Admin can edit dates and times.');
  const a=assignment(id),j=job(a.jobId),zone=workspaceZone();
  const startRequired=assignmentNeedsRecordedStart(a);
  const invoiceNote=state.invoices[j.id]?.paidAt?' A paid invoice keeps its issued amount.':'';
  modal('Admin · correct job times',`<form id="times-form">
    <p>${esc(j.number)} · ${esc(assignmentDriver(a).name)} · ${esc(a.truckUnit)}</p>
    <div class="notice">Enter times in ${esc(workspaceTimeZoneLabel(zone))}. Corrections are audited.${invoiceNote}</div>
    <div class="form-grid">
      ${field('Scheduled arrival','scheduled',j.scheduled?localStamp(j.scheduled):'','datetime-local')}
      ${field('Accepted / job start','startTime',a.startTime?localStamp(a.startTime):'','datetime-local',startRequired?'required':'')}
      ${field('On location','arrivalTime',a.arrivalTime?localStamp(a.arrivalTime):'','datetime-local')}
      ${field('Off location','departureTime',a.departureTime?localStamp(a.departureTime):'','datetime-local')}
      ${field('Yard return / job end','endTime',a.endTime?localStamp(a.endTime):'','datetime-local')}
    </div>
    ${field('Required correction reason','reason','','text','required maxlength="500"')}
    <div id="times-error" class="form-error" role="alert"></div>
    <div class="modal-foot"><button class="btn primary">Save audited correction</button></div>
  </form>`,'',true);
  $('#times-form').onsubmit=async event=>{
    event.preventDefault();
    const a=assignment(id),j=a&&job(a.jobId),form=new FormData(event.target);
    try{
      if(!isAdmin()||!j)throw new Error('Admin permission and a current assignment are required.');
      const values={};
      let previous=-Infinity;
      for(const key of ['startTime','arrivalTime','departureTime','endTime']){
        values[key]=parseWorkspaceField(form,key,a[key],zone);
        if(values[key]){
          const value=Date.parse(values[key]);
          if(value<previous)throw new Error('Times must follow start → arrival → departure → yard.');
          previous=value;
        }
      }
      if(a.status==='completed'&&(!values.startTime||!values.endTime))throw new Error('Completed jobs require start and end times.');
      if(assignmentNeedsRecordedStart(a)&&!values.startTime)throw new Error('An accepted or active assignment must keep its recorded start time.');
      const scheduled=parseWorkspaceField(form,'scheduled',j.scheduled,zone)||j.scheduled;
      Object.assign(a,values);
      j.scheduled=scheduled;
      if(state.invoices[j.id]&&!state.invoices[j.id].paidAt)state.invoices[j.id].total=calculateInvoice(j,assigned(j)).total;
      await save(`Admin time correction for ${j.number}: ${form.get('reason')}`);
      close();
      notify('Times corrected and recorded in the audit log.');
    }catch(error){
      const box=$('#times-error');
      if(box)box.textContent=error.message;
    }
  };
}
