      ${billingMode(a)==='hourly'?rateField('Hauling · $/hour','haul_'+a.id,a.hourlyRate??record.hourlyRate??0):rateField('Hauling · $/load','haul_'+a.id,a.loadRate??record.loadRate??0)}</div>
      <button type="button" class="btn small" data-action="edit-times" data-id="${esc(a.id)}">Correct this driver’s timestamps</button>
    </section>`).join('')}`;
  modal(paid?'Admin · edit invoice issue date':'Admin · edit invoice',`<form id="invoice-edit-form">
    <p>${esc(record.number)} · ${esc(record.customerName||record.operator)}</p>
