    ${chargeFields}${field('Required edit reason','reason','','text','required maxlength="500"')}
    <div id="invoice-edit-error" class="form-error" role="alert"></div><div class="modal-foot"><button class="btn primary">Save invoice revision</button></div>
  </form>`,'',true);
  $('#invoice-edit-form').onsubmit=async e=>{
    e.preventDefault();
    try{
      if(!isAdmin()||invoicePurged(id))throw new Error('This invoice can no longer be edited.');
