function field(label,name,value='',type='text',extra=''){
  const input=`<input type="${esc(type)}" name="${esc(name)}" value="${esc(value)}" ${extra}>`;
  if(type!=='datetime-local')return `<label class="field">${label}${input}</label>`;
  return `<div class="field"><label>${label}${input}</label><select name="${esc(name)}_offset" aria-label="Occurrence for ${label}" hidden disabled></select></div>`;
