function bindLocalTimeFields(root,zone){
  for(const input of root.querySelectorAll('input[type="datetime-local"]')){
    const offset=input.parentElement.nextElementSibling;
    const update=()=>{
      const selected=offset.value;
      const options=workspaceLocalDateOffsets(input.value,zone);
      offset.hidden=offset.disabled=options.length<2;
      offset.innerHTML='<option value="auto">Choose an occurrence if changing this repeated hour</option>'+
        options.map(({value,label})=>`<option value="${esc(value)}">${esc(label)}</option>`).join('');
      if(options.some(option=>option.value===selected))offset.value=selected;
    };
    input.addEventListener('change',update);
