    $('#job-well').innerHTML=allowed.length?allowed.map(well=>`<option value="${esc(well.id)}">${esc(well.wellName)} / ${esc(well.wellNumber)} · ${esc(well.operator)}</option>`).join(''):'<option value="">No wells for this customer</option>';
    updateWell();
  }
  function setFieldset(selector,enabled){
    const group=$(selector);
    if(group){group.hidden=!enabled;group.disabled=!enabled;}
  }
  function updateServices(){
    const manual=$('#manual-mode')?.checked===true;
    const legacy=manual&&$('#job-legacy-billing').value==='load';
    setFieldset('#manual-fields',manual);
    setFieldset('#legacy-load-fields',legacy);
    setFieldset('#job-pay-mode-field',legacy);
    setFieldset('#hourly-work-fields',!legacy);
    setFieldset('#job-fuel-surcharge-fields',$('#job-fuel-surcharge').checked===true);
    for(const {key} of HOURLY_FLUID_SERVICES){
      const chosen=!legacy&&$('#fluid-service-'+key).checked;
      setFieldset('#fluid-config-'+key,chosen);
      if(admin)for(const [index] of drivers.entries())setFieldset(`#manual-fluid-${index}-${key}`,chosen);
    }
    const choices=drivers.map((driver,index)=>({
      index,checkbox:$('#job-driver-'+index),busy:!manual&&busyDriver(driver.id)
    }));
    const limit=maxDriversPerJob();
    const selectedDrivers=choices.filter(({checkbox,busy})=>checkbox.checked&&!busy).map(({index})=>drivers[index]);
    const selected=selectedDrivers.length;
    $('#job-driver-limit').textContent=`${selected} selected · Limit ${limit} per job`;
    if(admin||can('view_payroll')){
      const defaults=selectedDrivers.map(driver=>`${driver.name} ${money(driver.rate??driver.hourlyRate??driver.payRate??0)}/h`);
      $('#job-driver-pay-defaults').textContent=`Leave blank to use each driver’s default hourly pay rate.${defaults.length?' '+defaults.join(' · '):''}`;
    }
    const hasFluid=HOURLY_FLUID_SERVICES.some(({key})=>$('#fluid-service-'+key).checked);
    for(const {index,checkbox,busy} of choices){
      if(busy)checkbox.checked=false;
      checkbox.disabled=busy||(!checkbox.checked&&selected>=limit);
      if(!admin)continue;
      for(const option of $('#job-truck-'+index).querySelectorAll('option')){
        option.disabled=Boolean(option.value)&&!manual&&busyTruck(option.value);
      }
      setFieldset('#manual-fluid-driver-'+index,manual&&!legacy&&checkbox.checked&&hasFluid);
    }
  }
  $('#job-representative-mode').addEventListener('change',updateRepresentativeMode);
  $('#job-arrival-rep').addEventListener('change',updateRepresentativeMode);
  $('#job-customer').addEventListener('change',updateCustomer);
  $('#job-well').addEventListener('change',updateWell);
  $('#manual-mode')?.addEventListener('change',updateServices);
  $('#job-legacy-billing')?.addEventListener('change',updateServices);
  for(const {key} of HOURLY_FLUID_SERVICES)$('#fluid-service-'+key).addEventListener('change',updateServices);
  $('#job-fuel-surcharge').addEventListener('change',updateServices);
  for(const [index] of drivers.entries())$('#job-driver-'+index).addEventListener('change',updateServices);
  updateCustomer();
  updateServices();

  $('#job-form').addEventListener('submit',async event=>{
    event.preventDefault();
    try{
      if(!can('dispatch_jobs'))throw new Error('This role cannot dispatch jobs.');
      const form=new FormData(event.target),ids=form.getAll('drivers');
      const manual=isAdmin()&&form.has('manual');
      const billingMode=manual&&form.get('historicalBilling')==='load'?'load':'hourly';
      const customer=customers.find(record=>record.id===form.get('customerId'));
      const well=wells.find(record=>record.id===form.get('wellId'));
      const representativeMode=form.get('representativeMode')||'single';
      const arrivalRep=reps.find(record=>record.id===(form.get('arrivalRepId')||form.get('repId')));
      const departureRep=representativeMode==='separate'?reps.find(record=>record.id===form.get('departureRepId')):arrivalRep;
      if(!customer)throw new Error('Choose an active customer.');
      if(well?.customerId&&well.customerId!==customer.id)throw new Error('Choose a well belonging to this customer.');
      if(!['single','separate'].includes(representativeMode))throw new Error('Choose one or two representatives.');
      if(!well||!arrivalRep||!departureRep)throw new Error('Choose an active well and representative for each step.');
      if(representativeMode==='separate'&&arrivalRep.id===departureRep.id)throw new Error('Choose two different representatives for arrival and departure.');
      if(!ids.length)throw new Error('Select at least one driver.');
      const limit=maxDriversPerJob();
      if(ids.length>limit)throw new Error(`Choose at most ${limit} ${limit===1?'driver':'drivers'} for this job.`);
      const selected=ids.map(id=>({
        driver:drivers.find(record=>record.id===id),
        truck:trucks.find(record=>record.id===form.get('truck_'+id))
      }));
      if(selected.some(pair=>!pair.driver||!pair.truck))throw new Error('Select an active driver and truck for every assignment.');
      if(new Set(selected.map(pair=>pair.truck.id)).size!==selected.length)throw new Error('Each driver needs a different truck for this job.');
      if(!manual&&selected.some(pair=>busyDriver(pair.driver.id)||busyTruck(pair.truck.id)))throw new Error('One selected driver or truck is already assigned.');
      const times={};
      if(manual){
        for(const key of ['startTime','arrivalTime','departureTime','endTime']){
          if(!form.get(key))throw new Error('All four manual timestamps are required.');
          times[key]=parseWorkspaceField(form,key,null,zone);
        }
        if(!(times.startTime<=times.arrivalTime&&times.arrivalTime<=times.departureTime&&times.departureTime<=times.endTime))throw new Error('Times must follow start → arrival → departure → yard.');
        if(new Date(times.endTime)>new Date())throw new Error('A completed job cannot end in the future.');
        if(!String(form.get('manualReason')||'').trim())throw new Error('Add the manual entry reason / source.');
        if(selected.some(({driver,truck})=>state.assignments.some(old=>(old.driverId===driver.id||old.truckId===truck.id)&&old.startTime&&new Date(old.startTime)<new Date(times.endTime)&&(!old.endTime||new Date(old.endTime)>new Date(times.startTime)))))throw new Error('Manual times overlap existing driver or truck work.');
      }
      const hourlyFluidServices=billingMode==='hourly'?readFluidOrder(form):{};
      const services=enabledHourlyFluidServices({hourlyFluidServices});
      const loadCount=billingMode==='load'?readDeliveryCount(form.get('loadCount'),'completed loads'):0;
      if(billingMode==='load'&&(loadCount<1||loadCount>100))throw new Error('Enter 1–100 completed loads per driver.');
      const rates={
        hourlyRate:billingMode==='hourly'?Number(form.get('hourlyRate')):0,
        loadRate:billingMode==='load'?Number(form.get('loadRate')):0,
        fluidSaleRate:billingMode==='load'?Number(form.get('fluidSaleRate')):0,
        fluidCostRate:billingMode==='load'?Number(form.get('fluidCostRate')):0
      };
      const includeFuelSurcharge=form.has('fuelSurcharge');
      const surchargeInput=form.get('fuelSurchargePercent');
      const fuelSurchargePercent=Number(surchargeInput);
      const hundredths=Math.round(fuelSurchargePercent*100);
      if(includeFuelSurcharge&&(typeof surchargeInput!=='string'||!surchargeInput.trim()||
         fuelSurchargePercent<0||!Number.isSafeInteger(hundredths)||hundredths/100!==fuelSurchargePercent)){
        throw new Error('Enter a nonnegative fuel surcharge percentage with up to two decimal places.');
      }
      const jobRecord={
        id:uid(),number:'JOB-'+(Math.max(1042,...state.jobs.map(item=>Number(item.number.split('-')[1])||0))+1),
        attachments:[],customerId:customer.id,customerName:customer.name,billingAddress:customer.billingAddress||'',
        wellId:well.id,representativeMode,arrivalRepId:arrivalRep.id,departureRepId:departureRep.id,repId:arrivalRep.id,
        service:billingMode==='load'?'Per-load hauling':['Hourly hauling',...services.map(({label})=>label)].join(' + '),
        notes:String(form.get('notes')||'').trim(),billingMode,...rates,
        ...(manual?{scheduled:times.arrivalTime}:{}),
        ...(services.length?{hourlyFluidServices}:{}),
        ...(includeFuelSurcharge?{fuelSurchargePercent}:{})
      };
      for(const key of ['operator','wellName','wellNumber','afe','county','rig','coordinates','directions'])jobRecord[key]=well[key]||'';
      const payRate=form.get('payRate');
      const assignments=selected.map(({driver,truck})=>{
        const index=drivers.indexOf(driver);
        return {
          id:uid(),jobId:jobRecord.id,driverId:driver.id,driverName:driver.name,truckId:truck.id,truckUnit:truck.unitNumber,
          status:manual?'completed':'assigned',...times,billingMode,...rates,
          payMode:billingMode==='load'&&form.get('payMode')==='percentage'?'percentage':'hourly',
          ...(payRate==null||payRate===''?{}:{payRate:Number(payRate)}),payPercent:billingMode==='load'?Number(form.get('payPercent')):0,
          standbyCharge:manual?Number(form.get('standbyCharge')):0,washoutCost:manual?Number(form.get('washoutCost')):0,
          loads:Array.from({length:loadCount},()=>({id:uid(),qtyBbl:Number(form.get('qtyBbl')),completedTime:times.endTime})),
          pauses:[],signatures:[],deliveryPhotos:[],manual,manualReason:manual?form.get('manualReason'):null,
          ...(manual&&services.length?{hourlyFluidQuantities:readFluidCounts(form,services,`actual_${index}_`)}:{})
        };
      });
      state.jobs.unshift(jobRecord);
      state.assignments.push(...assignments);
      await save(`${jobRecord.number} created from well ${well.id} with ${assignments.length} driver/truck assignments${manual?' · manual import: '+form.get('manualReason'):''}.`);
      close();
      view='dispatch';
      render();
      notify(`${jobRecord.number} created.`);
    }catch(error){
      const box=$('#form-error');
      if(box)box.textContent=error.message;
    }
  });
}

function jobDetail(id){const j=job(id),aa=assigned(j);modal(`${esc(j.number)} · ${esc(j.operator)}`,`<div class="detail-grid"><div class="summary-list">${[['Customer',j.customerName||j.operator],['Well',`${j.wellName} / ${j.wellNumber}`],['Rig',j.rig],['AFE',j.afe],['County',j.county],['Coordinates',j.coordinates],['Scheduled arrival',date(j.scheduled)],['Created by',j.createdByName||'Not recorded'],['Dispatcher',j.dispatcherName||state.defaultDispatchContact?.name||'Not assigned'],...representativeRows(j),['Customer billing',j.billingMode==='hourly'?money(j.hourlyRate)+'/hour':money(j.loadRate)+'/load'],...(j.fuelSurchargePercent!==undefined?[['Fuel surcharge',num(j.fuelSurchargePercent)+'%']]:[]),...enabledHourlyFluidServices(j).map(({key,label})=>[label,`${num(j.hourlyFluidServices[key].estimatedQuantity)} estimated · ${money(j.hourlyFluidServices[key].rate)} per delivery`]),...(j.fluidSaleRate||j.fluidCostRate?[["Fluid sell / purchase",money(j.fluidSaleRate)+' / '+money(j.fluidCostRate)+' per bbl']]:[])].map(([l,v])=>`<div class="summary-row"><span>${l}</span><strong>${esc(v||'—')}</strong></div>`).join('')}</div><div><h3>Directions</h3><p>${esc(j.directions)}</p><h3>Additional details</h3><p>${esc(j.notes)}</p>${attachmentsHtml(j)}${!state.invoices[j.id]&&can('dispatch_jobs')?`<label class="field">Add an attachment (max 250 KB)<input type="file" id="attachment" accept=".pdf,.jpg,.jpeg,.png,.txt,.csv"></label><p class="cell-sub">Files are shared with assigned drivers.</p>`:''}</div></div><h3>Driver assignments</h3><div class="table-wrap"><table><thead><tr><th>Driver</th><th>Status</th><th>Pay method</th><th></th></tr></thead><tbody>${aa.map(a=>`<tr><td><span class="cell-main">${esc(assignmentDriver(a).name)}</span><span class="cell-sub">${esc(assignmentDriver(a).truck)}</span>${a.completionNote?`<p class="cell-sub completion-note"><strong>Completion note</strong><br>${esc(a.completionNote)}</p>`:''}</td><td>${badge(titleCase(a.status),a.status==='completed'?'gray':'green')}${a.manual?'<span class="cell-sub">Manual import</span>':''}</td><td>${can('view_payroll')?(a.payMode==='hourly'?money(a.payRate)+'/h':num(a.payPercent)+'% haul'):'Restricted'}</td><td>${isAdmin()?dataButton('edit-times','Edit times',`data-id="${esc(a.id)}"`,'btn small'):''} ${isAdmin()&&!state.invoices[j.id]?.paidAt?dataButton('charges','Extra charges',`data-id="${esc(a.id)}"`,'btn small'):''} ${can('view_invoices')?dataButton('ticket','Ticket',`data-id="${esc(a.id)}"`,'btn small'):''}</td></tr>`).join('')}</tbody></table></div>`,can('view_invoices')&&!invoicePurged(j.id)?dataButton('invoice','Review invoice '+icon('arrow'),`data-id="${esc(j.id)}"`):'',true);$('#attachment')?.addEventListener('change',async e=>{if(!can('dispatch_jobs'))return;const f=e.target.files[0];if(!f)return;if(f.size>250*1024){notify('Choose a file no larger than 250 KB.');return;}const allowed=['application/pdf','image/jpeg','image/png','text/plain','text/csv'];if(!allowed.includes(f.type)&&!f.name.toLowerCase().endsWith('.csv')){notify('Use PDF, JPG, PNG, TXT or CSV.');return;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});j.attachments.push({id:uid(),name:f.name,type:f.type,data});try{await save(`Attachment ${f.name} added to ${j.number}.`);jobDetail(id);notify('Attachment saved for the assigned drivers.');}catch{j.attachments.pop();}});}
function sigPad(id){return `<div class="signature"><canvas id="${id}" width="600" height="170" aria-label="Draw signature here"></canvas><div class="job-card-head"><small>Draw your signature with a finger, stylus or mouse.</small><button type="button" class="text-btn" data-clear="${id}">Clear</button></div></div>`;}
function setupCanvas(id){const c=$('#'+id),ctx=c.getContext('2d');ctx.strokeStyle='#142b27';ctx.lineWidth=2.5;ctx.lineCap='round';let drawing=false,points=0;const pos=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height];};c.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...pos(e));});c.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineTo(...pos(e));ctx.stroke();points++;c.dataset.signed=points>2?'yes':'';});c.addEventListener('pointerup',()=>drawing=false);c.addEventListener('pointercancel',()=>drawing=false);$(`[data-clear="${id}"]`).onclick=()=>{ctx.clearRect(0,0,c.width,c.height);points=0;c.dataset.signed='';};}
function representativeFor(value){const j=job(value);return state.representatives.find(r=>r.id===(j?.repId||value));}
function configurePin(value){if(!isAdmin())throw new Error('Only Admin can set representative PINs.');const rep=representativeFor(value);if(!rep)throw new Error('Representative not found.');modal(`Set PIN · ${esc(rep.name)}`,`<form id="pin-form"><p>Give this personal code to the representative directly. Drivers cannot view or reset it.</p>${field('New four-digit PIN','pin','','password','inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required autocomplete="new-password"')}${field('Repeat PIN','confirm','','password','inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required autocomplete="new-password"')}<div id="pin-error" class="form-error" role="alert"></div><div class="modal-foot"><button class="btn primary">Save PIN</button></div></form>`);$('#pin-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('pin')!==f.get('confirm')){$('#pin-error').textContent='PINs must match.';return;}try{setBusy(true);await api.setPin(rep.id,f.get('pin'));await refreshWorkspace();close();notify('Representative PIN saved securely.');}catch(error){$('#pin-error').textContent=error.message;}finally{setBusy(false);}};}
function signatureFlow(id,kind){
  const a=assignment(id);
  if(!a||!isDriverMode()||a.driverId!==selectedDriver)throw new Error('This assignment belongs to another driver.');
  if(kind==='arrival'&&!a.jsa?.signed){notify('STOP: Complete safety sign-off first.');return;}
  if(kind==='departure'&&missingPerLoadRecords(a))throw new Error('Record at least one completed load before confirming departure.');
  const j=job(a.jobId),services=kind==='departure'?enabledHourlyFluidServices(j):[];
  const expectedRep=representativeForJob(j,kind),rep=state.representatives.find(record=>record.id===expectedRep.id);
  if(!rep?.pinConfigured){
    modal('Representative code is not configured','<p>Ask Admin to issue the representative’s personal PIN before continuing.</p>');
    return;
  }
  modal(services.length?'Finish work · confirm water deliveries':'Representative · unlock signature',`<form id="unlock-form">
    <p>${esc(j.number)} · ${esc(j.wellName)} · ${kind==='jsa'?'Safety sign-off':titleCase(kind)}</p>
    ${services.length?`<h3>Actual water deliveries</h3><p class="cell-sub">Order estimates are filled in. Driver, check the numbers against your actual deliveries. The representative reviews the counts before signing.</p><div class="form-grid">${services.map(({key,label})=>deliveryCountField(`${deliveryLabel(label)} deliveries`,'actual_'+key,j.hourlyFluidServices[key].estimatedQuantity)).join('')}</div>`:''}
    <div class="notice">${icon('shield')} <span><strong>${esc(expectedRep.name)}</strong>, enter your PIN to unlock the signature.</span></div>
    ${field('Representative PIN','pin','','password','inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" required')}
    <div id="unlock-error" class="form-error" role="alert"></div>
    <div class="modal-foot"><button class="btn primary">Unlock signature</button></div>
  </form>`);
  const form=$('#unlock-form');
  form.onsubmit=async event=>{
    event.preventDefault();
    const button=form.querySelector('.btn.primary');
    button.disabled=true;
    try{
      const values=new FormData(form);
      const hourlyFluidQuantities=services.length?readFluidCounts(values,services,'actual_'):undefined;
      const result=await api.unlockSignature(id,kind,values.get('pin'),hourlyFluidQuantities);
      if($('#unlock-form')!==form)return;
      const authorization={token:result.unlockToken,expires:new Date(result.expiresAt).getTime(),used:false,hourlyFluidQuantities,jsaTemplate:result.jsaTemplate};
      if(kind==='jsa')openJsaReview(id,authorization);
      else openUnlockedSignature(id,kind,authorization);
    }catch(error){
      if($('#unlock-form')===form)$('#unlock-error').textContent=error.message;
    }finally{button.disabled=false;}
  };
}

function openJsaReview(id,authorization){
  const template=authorization.jsaTemplate,url=jsaTemplateUrl(template);
  if(!url)throw new Error('Reload this page and verify the representative PIN to open the JSA PDF.');
  modal('JSA safety review',`<form id="jsa-review-form">
    <p><strong>${esc(template.name)}</strong></p>
    <p>Driver and representative, read the complete JSA PDF before continuing.</p>
    <p id="jsa-review-status" class="cell-sub" role="status">Loading the JSA PDF…</p>
    <iframe id="jsa-review-frame" class="jsa-review-frame" title="JSA safety PDF" hidden></iframe>
    <p><a id="jsa-review-open" href="#" target="_blank" rel="noopener" hidden>Open the PDF in a new tab</a></p>
    <label class="checkbox-row"><input type="checkbox" id="jsa-driver-confirmed" disabled> Driver: I have read and understood the JSA PDF.</label>
    <label class="checkbox-row"><input type="checkbox" id="jsa-representative-confirmed" disabled> Representative: I have read and understood the JSA PDF.</label>
    <div id="jsa-review-error" class="form-error" role="alert"></div>
    <div class="modal-foot"><button class="btn primary" id="jsa-review-acknowledge" disabled>Continue to signatures</button></div>
  </form>`,'',true);
  const form=$('#jsa-review-form'),status=$('#jsa-review-status');
  const frame=$('#jsa-review-frame'),open=$('#jsa-review-open'),error=$('#jsa-review-error');
  const driverConfirmed=$('#jsa-driver-confirmed'),representativeConfirmed=$('#jsa-representative-confirmed');
  const button=$('#jsa-review-acknowledge'),controller=new AbortController();
  let previewUrl;
  modalCleanups.push(()=>{
    controller.abort();
    if(previewUrl)URL.revokeObjectURL(previewUrl);
  });
  const updateButton=()=>{button.disabled=!(previewUrl&&driverConfirmed.checked&&representativeConfirmed.checked);};
  driverConfirmed.addEventListener('change',updateButton);
  representativeConfirmed.addEventListener('change',updateButton);
  form.addEventListener('submit',event=>{
    event.preventDefault();
    if(button.disabled)return;
    if(Date.now()>authorization.expires){
      error.textContent='The signature unlock expired. Close this review and verify the representative PIN again.';
      return;
    }
    const acknowledgement={templateId:template.id,driver:true,representative:true};
    openUnlockedSignature(id,'jsa',{...authorization,acknowledgement});
  });

  void (async()=>{
    try{
      const response=await fetch(url,{
        headers:{'X-JSA-Review-Token':authorization.token},credentials:'same-origin',
        mode:'same-origin',cache:'no-store',signal:controller.signal
      });
      if(!response.ok||response.headers.get('Content-Type')?.split(';',1)[0]!=='application/pdf')throw new Error('PDF unavailable.');
      const file=await response.blob();
      if(file.size!==template.bytes)throw new Error('Incomplete PDF.');
      if(controller.signal.aborted)return;
      previewUrl=URL.createObjectURL(file);
      frame.src=previewUrl;
      open.href=previewUrl;
      frame.hidden=open.hidden=false;
      status.textContent='';
      driverConfirmed.disabled=representativeConfirmed.disabled=false;
      updateButton();
    }catch{
      if(controller.signal.aborted)return;
      status.textContent='';
      error.textContent='The JSA PDF could not be opened. Close this review and verify the representative PIN to try again.';
    }
  })();
}

function openUnlockedSignature(id,kind,authorization){
  const a=assignment(id),j=job(a.jobId),rep=representativeForJob(j,kind);
  const isJsa=kind==='jsa',quantities=authorization.hourlyFluidQuantities;
  if(isJsa&&!authorization.acknowledgement)throw new Error('Both participants must confirm the JSA PDF before signing.');
  const confirmed=quantities?fluidQuantityRows(enabledHourlyFluidServices(j),quantities):[];
  modal(isJsa?'JSA sign-off':`Sign ${kind==='arrival'?'arrival on':'departure from'} location`,`<form id="signature-form">
    <div class="notice">${icon('check')} <span><strong>PIN verified by the server.</strong> Complete this step before the unlock expires.</span></div>
    ${isJsa?`<p><strong>Reviewed PDF</strong> · ${esc(authorization.jsaTemplate.name)}</p>`:''}
    <p>${esc(j.number)} · ${esc(j.wellName)}</p>
    ${confirmed.length?`<h3>Review actual deliveries before signing</h3><div class="summary-list">${confirmed.map(([label,value])=>`<div class="summary-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div>`:''}
    ${isJsa?`<p class="notice">${esc(JSA_ACKNOWLEDGEMENT_TEXT)}</p><h3>Driver · ${esc(assignmentDriver(a).name)}</h3>${sigPad('driver-signature')}`:''}
    <h3>${kind==='departure'?'Departure':'Arrival'} representative · ${esc(rep.name)}</h3>
    ${sigPad('rep-signature')}
    <div id="signature-error" class="form-error" role="alert"></div>
    <div class="modal-foot"><button class="btn primary">Record ${isJsa?'safety sign-off':confirmed.length?'deliveries and departure':kind}</button></div>
  </form>`,'',true);
  setupCanvas('rep-signature');
  if(isJsa)setupCanvas('driver-signature');
  const form=$('#signature-form'),button=form.querySelector('.btn.primary');
  form.onsubmit=async event=>{
    event.preventDefault();
    const errorBox=$('#signature-error');
    if(saving||button.disabled)return;
    if(authorization.used||Date.now()>authorization.expires){
      errorBox.textContent='This unlock expired. Close the panel and verify the PIN again.';
      return;
    }
    const repPad=$('#rep-signature'),driverPad=$('#driver-signature');
    if(repPad.dataset.signed!=='yes'||(isJsa&&driverPad.dataset.signed!=='yes')){
      errorBox.textContent='Each required person must draw their signature.';
      return;
    }
    const repSignature=repPad.toDataURL(),driverSignature=isJsa?driverPad.toDataURL():undefined;
    button.disabled=true;
    try{
      // The signer may keep the panel open while other accounts save their work.
      await refreshWorkspace();
      if($('#signature-form')!==form)return;
      const a=assignment(id),j=a&&job(a.jobId);
      const expectedStatus=kind==='departure'?'on-location':'accepted';
      if(!j||a.driverId!==selectedDriver||!isDriverMode()||a.status!==expectedStatus||
         (isJsa&&a.jsa?.signed)||(kind==='arrival'&&!a.jsa?.signed)){
        throw new Error('The assignment has moved to another step. Close this panel to continue.');
      }
      if(kind==='departure'&&missingPerLoadRecords(a))throw new Error('Record at least one completed load before confirming departure.');
      if(Date.now()>authorization.expires)throw new Error('This unlock expired. Close the panel and verify the PIN again.');
      const rep=representativeForJob(j,kind);
      const record={at:now(),repId:rep.id,repName:rep.name,repSignature,pinVerified:true,pinVerifiedBeforeSignature:true,kind};
      if(isJsa){
        a.jsa={signed:true,acknowledgement:authorization.acknowledgement,signedAt:record.at,driverName:assignmentDriver(a).name,driverSignature,...record};
      }else{
        if(quantities)a.hourlyFluidQuantities=quantities;
        a.signatures||=[];
        a.signatures.push(record);
        a[kind==='arrival'?'arrivalTime':'departureTime']=record.at;
        a.status=kind==='arrival'?'on-location':'off-location';
      }
      await save(`${j.number}: ${kind} signed.`,{signatureUnlockToken:authorization.token});
      authorization.used=true;
      close();
      notify(isJsa?'JSA signed. Confirm arrival when you are on location.':quantities?'Deliveries confirmed. Complete the job after returning to the yard.':'Signature recorded.');
    }catch(error){
      if($('#signature-form')===form)errorBox.textContent=error.message;
    }finally{button.disabled=false;}
  };
}

function addLoad(id,{recovery=false}={}){
  const a=assignment(id),j=a&&job(a.jobId);
  if(!j)throw new Error('Assignment not found.');
  const volumeLabel='Fluid volume · barrels (enter 0 for tools or materials)';
  const inputs=recovery?`
    <label class="field">Barrels per completed load<textarea name="volumes" rows="4" maxlength="2000" required></textarea></label>
    <p class="cell-sub">Enter one volume per line. Use 0 for a load of tools or materials. Include every missed load before saving.</p>
    ${field('Reason or source record','recoveryReason','','text','required maxlength="500"')}
  `:field(volumeLabel,'qtyBbl',0,'number','min="0" step="0.01" required');
  modal(recovery?'Record missed loads':'Record a completed load',`<form id="load-form">
    <p><strong>${esc(j.number)}</strong> · ${esc(j.wellName)} · ${esc(a.truckUnit)}</p>
    ${inputs}
    <label class="field">Delivery notes<textarea name="description" rows="2" maxlength="1000" placeholder="What was delivered?"></textarea></label>
    <div class="form-error" id="load-error" role="alert"></div>
    <div class="modal-foot"><button class="btn primary">${recovery?'Save missed loads':'Record completed load'}</button></div>
  </form>`);
  $('#load-form').onsubmit=async event=>{
    event.preventDefault();
    if(saving)return;
    const a=assignment(id),j=a&&job(a.jobId);
    try{
      if(!j||!isDriverMode()||!can('driver_work')||a.driverId!==selectedDriver||
         (recovery?!canRecoverMissedLoads(a):a.status!=='on-location')){
        throw new Error('Load entry is no longer available for this assignment.');
      }
      const form=new FormData(event.target);
      const values=recovery?String(form.get('volumes')||'').split(/\r?\n/).map(value=>value.trim()).filter(Boolean):[form.get('qtyBbl')];
      if(!values.length||values.length>100||values.some(value=>!(/^(?:\d+(?:\.\d{0,2})?|\.\d{1,2})$/).test(value)||!Number.isFinite(Number(value)))){
        throw new Error('Enter up to 100 nonnegative volumes with at most two decimal places.');
      }
      const recoveryReason=recovery?String(form.get('recoveryReason')||'').trim():null;
      if(recovery&&!recoveryReason)throw new Error('Enter a reason or source record.');
      const description=String(form.get('description')||'').trim();
      a.loads||=[];
      for(const value of values)a.loads.push({id:uid(),qtyBbl:Number(value),description,...(recovery?{recoveryReason}:{})});
      await save(`${j.number} · ${recovery?'Missed loads recorded':'Completed load recorded'} for ${assignmentDriver(a).name}.`);
      close();
      notify(recovery?'Missed loads recorded. Complete the job after returning to the yard.':'Completed load recorded.');
    }catch(error){
      const box=$('#load-error');
      if(box)box.textContent=error.message;
    }
  };
}

