function ticketHtml(a,{load=null,loadIndex=0,groupLoads=false}={}){
  if(a.billingMode==='load'&&!load&&!groupLoads&&a.loads?.length){
    return a.loads.map((item,index)=>ticketHtml(a,{load:item,loadIndex:index})).join('');
  }
  const j=job(a.jobId),driver=assignmentDriver(a);
  const source=load?{
    ...a,loads:[load],standbyCharge:loadIndex===0?a.standbyCharge:0,washoutCost:loadIndex===0?a.washoutCost:0
  }:a;
  const ticket=calculateTicket(source,j);
  const charges=ticket.billingMode==='hourly'
    ? [['Hourly hauling',num(ticket.billableHours)+' h',money(a.hourlyRate??j.hourlyRate),money(ticket.haulTotal)]]
    : ticket.loadTickets.map((item,index)=>[
        `Load ticket ${load?loadIndex+1:index+1} · ${item.id}`,'1 load',money(a.loadRate??j.loadRate),money(item.haulTotal)
      ]);
  for(const item of ticket.hourlyFluidItems){
    charges.push([item.label,num(item.quantity)+' deliveries',money(item.rate)+'/delivery',money(item.total)]);
  }
  for(const item of ticket.loadTickets){
    if(item.qtyBbl>0&&(item.fluidTotal>0||!enabledHourlyFluidServices(j).length)){
      charges.push([`Fluid · load ${item.id}`,num(item.qtyBbl)+' bbl',money(item.fluidTotal/item.qtyBbl)+'/bbl',money(item.fluidTotal)]);
    }
  }
  charges.push(['Additional standby','—','—',money(ticket.standbyTotal)],['Washout','—','—',money(ticket.washoutTotal)]);
  const facts=[
    ['Operator',j.operator],['Well / number',`${j.wellName} / ${j.wellNumber}`],
    ['Rig / AFE',`${j.rig} / ${j.afe}`],['County',j.county],
    ...representativeRows(j),['Driver / unit',`${driver.name} / ${driver.truck}`],['Service',jobServiceLabel(j)],
  ];
  const timeline=[
    ['Accepted / job start',a.startTime],['On location',a.arrivalTime],
    ['Off location',a.departureTime],['Yard / job end',a.endTime]
  ];
  const signatures=[];
  if(a.jsa?.driverSignature)signatures.push({
    label:'JSA driver',detail:a.jsa.driverName||driver.name,src:a.jsa.driverSignature,alt:'Driver JSA signature'
  });
  if(a.jsa?.repSignature)signatures.push({
    label:'JSA representative',detail:`${a.jsa.repName||'Representative'} · PIN verified`,src:a.jsa.repSignature,alt:'Representative JSA signature'
  });
  for(const signature of a.signatures||[]){
    const counts=signature.hourlyFluidQuantities||{};
    const signedDeliveries=HOURLY_FLUID_SERVICES.filter(({key})=>Object.hasOwn(counts,key)).map(({key,label})=>`${label}: ${num(counts[key])}`).join(' · ');
    signatures.push({
      label:titleCase(signature.kind||'Representative'),detail:`${signature.repName||'Representative'} · ${date(signature.at)} · PIN verified`,
      src:signature.repSignature,alt:`Representative ${signature.kind||''} signature`,signedDeliveries
    });
  }
  const loadDetails=(source.loads||[]).filter(item=>item.completedTime||item.description);
  return `<article class="ticket compact-field-ticket">
    <header class="ticket-heading">
      <div>${companyLogoHtml('ticket-company-logo')}<span class="cell-sub">${esc(state.invoices[j.id]?.companyName||state.company)}</span>
        <h2>Field ticket${load?' · load '+(loadIndex+1):''}</h2><p>${esc(j.number)} · ${esc((load?.id||a.id).slice(0,8).toUpperCase())}</p></div>
      ${badge(a.manual?'Manual import':titleCase(a.status),a.status==='completed'?'green':'orange')}
    </header>
    <dl class="ticket-facts">${facts.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value||'—')}</dd></div>`).join('')}</dl>
    <div class="table-wrap"><table class="ticket-table"><thead><tr>${timeline.map(([label])=>`<th scope="col">${label}</th>`).join('')}<th scope="col">Billable hours</th></tr></thead>
      <tbody><tr>${timeline.map(([,timestamp])=>`<td>${esc(date(timestamp))}</td>`).join('')}<td>${num(ticket.billableHours)} h</td></tr></tbody></table></div>
    <div class="table-wrap"><table class="ticket-table">
      <thead><tr><th scope="col">Description</th><th scope="col" class="right">Quantity</th><th scope="col" class="right">Rate</th><th scope="col" class="right">Amount</th></tr></thead>
      <tbody>${charges.map(([label,quantity,rate,amount])=>`<tr><th scope="row">${esc(label)}</th><td class="right">${esc(quantity)}</td><td class="right">${esc(rate)}</td><td class="right">${esc(amount)}</td></tr>`).join('')}</tbody>
      <tfoot><tr><th colspan="3" scope="row">Ticket total · before tax</th><td class="right"><strong>${money(ticket.total)}</strong></td></tr></tfoot>
    </table></div>
    ${loadDetails.length?`<div class="table-wrap"><table class="ticket-table"><thead><tr><th scope="col">Load reference</th><th scope="col">Recorded</th><th scope="col">Delivery notes</th></tr></thead>
      <tbody>${loadDetails.map(item=>`<tr><td>${esc(item.id||'—')}</td><td>${esc(date(item.completedTime))}</td><td>${esc(item.description||'—')}</td></tr>`).join('')}</tbody>
    </table></div>`:''}
    ${irregularities(a)}
    ${a.manual?`<p class="cell-sub">Manual office import · ${esc(a.manualReason)}</p>`:''}${signatures.length?`<section class="ticket-evidence"><h3>Signatures</h3><div class="ticket-evidence-grid">
      ${signatures.map(signature=>`<figure class="ticket-signature"><figcaption><strong>${esc(signature.label)}</strong><span class="cell-sub">${esc(signature.detail)}</span>
        ${signature.signedDeliveries?`<span class="cell-sub">${esc(signature.signedDeliveries)}</span>`:''}</figcaption>
        ${typeof signature.src==='string'&&/^data:image\/(?:png|jpeg);base64,[A-Za-z0-9+/=\r\n]+$/.test(signature.src)?`<img src="${esc(signature.src)}" alt="${esc(signature.alt)}">`:'<span class="cell-sub">Signature image unavailable.</span>'}</figure>`).join('')}
      </div></section>`:''}
    ${(!load||loadIndex===0)?showDeliveryPhotos(a,context()):''}
    <p class="cell-sub">Field document · ${esc(workspaceTimeZoneLabel(workspaceZone()))}</p>
  </article>`;
}
