async function downloadInvoice(id,{print=false}={}){
  if(!can('view_invoices'))throw new Error('This role cannot download invoices.');
  if(invoicePurged(id))throw new Error('This invoice has been permanently deleted.');
  if(pdfDownloading)return;
  const j=job(id);
  if(!j)throw new Error('Invoice not found.');
  const viewer=print?window.open('','_blank'):null;
  if(print&&!viewer)throw new Error('Allow pop-ups to open the complete invoice for printing.');
  if(viewer){
    viewer.opener=null;
    viewer.document.title='Preparing invoice';
    viewer.document.body.textContent='Preparing the complete invoice…';
  }
  const controls=[...document.querySelectorAll('[data-action="invoice-download"], [data-action="invoice-print-pdf"]')];
  pdfDownloading=true;
  for(const button of controls)button.disabled=true;
  try{
    notify('Preparing the complete invoice…');
    const pdf=await buildInvoicePdf(invoiceContext(),j,{logoUrl:getCompanyLogoUrl()});
    if(viewer){
      if(viewer.closed)return;
      const url=URL.createObjectURL(new Blob([pdf.bytes],{type:pdf.mime}));
      viewer.location.replace(url);
      setTimeout(()=>URL.revokeObjectURL(url),5*60*1000);
      notify('Complete invoice PDF opened for printing.');
    }else{
      download(pdf.filename,pdf.bytes,pdf.mime);
      notify('Complete invoice PDF downloaded.');
    }
  }catch(error){
    viewer?.close();
    throw error;
  }finally{
    pdfDownloading=false;
    for(const button of controls)button.disabled=false;
  }
}
