function payrollCsv(){const week=currentPayrollWeek(),p=weeklyPayroll(state.assignments,state.drivers,week,workspaceZone()),rows=[['Week beginning','Driver','Total worked hours','Hourly hours','Regular hours','Overtime hours','Regular pay USD','Overtime pay USD','Percentage pay USD','Total pay USD'],...p.drivers.map(r=>[week,driver(r.driverId)?.name||r.driverId,r.workedHours,r.hours,r.regularHours,r.overtimeHours,r.regularPay,r.overtimePay,r.percentagePay,r.totalPay])];const cell=v=>'"'+String(typeof v==='number'?Math.round(v*100)/100:v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download(`payroll-${week}.csv`,rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');notify('Payroll CSV exported. Email delivery is not connected.');}
function bindWorkReport(){
