let workspacePollPending=false;
const workspaceEditorOpen=()=>Boolean($('#modal-root')?.innerHTML||
  (view==='masters'&&masterTab==='jsa-pdf'&&$('#jsa-pdf-file')?.files?.length));
async function pollWorkspace(){
  if(!authUser||isCustomerSupervisor()||saving||workspacePollPending||document.visibilityState==='hidden'||workspaceEditorOpen())return;
  const account=authUser;workspacePollPending=true;
  try{
    const [data]=await Promise.all([api.getWorkspace(),loadCompanyBranding(api)]);
    if(authUser!==account||saving||workspaceEditorOpen()||!data.state||data.revision<revision)return;
    const changed=data.revision!==revision;
    const locationChanged=view==='tracking'&&JSON.stringify(state.locations)!==JSON.stringify(data.state.locations||{});
    state={...blankState(),...data.state};revision=data.revision;mapReadStatus={at:now(),error:''};
    if(view==='live-maps'&&can('view_tracking')&&!isDriverMode()){
      if(changed)refreshRuntimeClock();
      liveMap?.update(context(),liveMapUi);
    }else if(changed||locationChanged)render();
  }catch(error){if(authUser===account){mapReadStatus={...mapReadStatus,error:'Unable to refresh. Showing last received locations.'};if(view==='live-maps')liveMap?.update(context(),liveMapUi);}}
  finally{workspacePollPending=false;}
}
setInterval(pollWorkspace,30000);

function refreshRuntimeClock(){
  const clock=$('#workspace-clock'),label=$('#workspace-zone-label');
  if(!clock)return;
  const at=new Date(Date.now()+serverClockOffset),zone=workspaceZone();
  const zoneLabel=workspaceTimeZoneLabel(zone);
  if(label&&label.textContent!==zoneLabel)label.textContent=zoneLabel;
  const office=$('#office-zone-label');
  if(office&&office.textContent!==zoneLabel)office.textContent=zoneLabel;
  clock.textContent=formatWorkspaceClock(at,zone);
  clock.setAttribute('datetime',at.toISOString());
}
function updateConnectionUi(status,snapshot={}){
  const labels={connected:'Connected',connecting:'Connecting',disconnected:'Disconnected'};if(!labels[status])status='disconnected';
  const label=$('#connection-label'),indicator=$('#connection-indicator');
  if(label&&label.textContent!==labels[status])label.textContent=labels[status];
  if(indicator){indicator.className='connection-indicator '+status;indicator.setAttribute('data-state',status);indicator.setAttribute('aria-label','Server connection: '+labels[status]);}
  if(status==='connected'&&Number.isFinite(Date.parse(snapshot.serverTime)))serverClockOffset=Date.parse(snapshot.serverTime)-Date.now();
  refreshRuntimeClock();
}
